import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { callGemini } from './gemini-client.js';

async function main() {
  const issueNumber = process.env.ISSUE_NUMBER;

  if (!issueNumber) {
    console.error('Error: ISSUE_NUMBER is required.');
    process.exit(1);
  }

  console.log(`Starting fix workflow for issue #${issueNumber}`);

  let issueData;
  try {
    const raw = execFileSync('gh', ['issue', 'view', issueNumber, '--json', 'title,body,comments,labels'], { encoding: 'utf8' });
    issueData = JSON.parse(raw);
  } catch (e) {
    console.error(`Failed to fetch issue #${issueNumber}:`, e.message);
    process.exit(1);
  }

  const promptPath = path.resolve('.github/prompts/fix.md');
  const systemInstruction = fs.readFileSync(promptPath, 'utf8');

  // Collect key files for context
  const filesToInclude = [
    'package.json',
    'js/constants.js',
    'js/sysex.js',
    'js/program.js',
    'js/midi.js',
    'js/librarian.js',
    'js/ui.js',
    'js/app.js'
  ];

  let codebaseContext = '';
  for (const relPath of filesToInclude) {
    if (fs.existsSync(relPath)) {
      const content = fs.readFileSync(relPath, 'utf8');
      codebaseContext += `\n\n=== File: ${relPath} ===\n${content}\n`;
    }
  }

  const thread = (issueData.comments || []).map(c => `[${c.author.login}]: ${c.body}`).join('\n\n---\n\n');

  const userPrompt = `
Issue #${issueNumber}: ${issueData.title}

Issue Description:
${issueData.body}

Discussion Thread:
${thread}

Key Source Files:
${codebaseContext}

Analyze the problem, formulate the solution, and generate the JSON payload containing the files to modify/create and PR details.
`;

  try {
    const result = await callGemini({
      systemInstruction,
      prompt: userPrompt,
      temperature: 0.1
    });

    console.log('Fix proposal received:', result.pr_title);

    if (!Array.isArray(result.files) || result.files.length === 0) {
      throw new Error('Gemini proposed no file modifications.');
    }

    const branchName = `fix/issue-${issueNumber}`;

    // Configure git user
    execFileSync('git', ['config', 'user.name', 'github-actions[bot]']);
    execFileSync('git', ['config', 'user.email', '41898282+github-actions[bot]@users.noreply.github.com']);

    // Check out new branch
    execFileSync('git', ['checkout', '-B', branchName]);

    // Apply file changes
    for (const f of result.files) {
      const targetPath = path.resolve(f.path);
      // Security check: ensure path is inside repo
      if (!targetPath.startsWith(process.cwd())) {
        console.warn(`Skipping invalid path outside repo: ${f.path}`);
        continue;
      }

      if (f.action === 'delete') {
        if (fs.existsSync(targetPath)) {
          fs.unlinkSync(targetPath);
          console.log(`Deleted: ${f.path}`);
        }
      } else {
        fs.mkdirSync(path.dirname(targetPath), { recursive: true });
        fs.writeFileSync(targetPath, f.content, 'utf8');
        console.log(`Updated/Created: ${f.path}`);
      }
    }

    // Run test suite
    console.log('Running test suite (npm test)...');
    try {
      execFileSync('npm', ['test'], { stdio: 'inherit' });
      console.log('Tests passed successfully!');
    } catch (testErr) {
      console.error('Tests failed after applying fix!');
      // Mark issue with fix-failed label and comment
      try {
        execFileSync('gh', ['issue', 'edit', issueNumber, '--add-label', 'agent:fix-failed']);
        execFileSync('gh', ['issue', 'comment', issueNumber, '--body', '⚠️ Agent attempted a fix but tests failed. Human review requested.']);
      } catch (e) {}
      process.exit(1);
    }

    // Commit changes
    execFileSync('git', ['add', '-A']);
    const commitMsg = result.commit_message || `fix: resolve issue #${issueNumber}\n\nCo-authored-by: Gemini Agent <actions@github.com>`;
    execFileSync('git', ['commit', '-m', commitMsg]);

    // Push branch
    execFileSync('git', ['push', '-u', 'origin', branchName, '--force']);
    console.log(`Pushed branch ${branchName}`);

    // Create Pull Request
    const prTitle = result.pr_title || `fix: address issue #${issueNumber}`;
    const prBody = `${result.pr_description || ''}\n\nCloses #${issueNumber}\n\n*Automated PR generated by Gemini Fix Agent*`;

    execFileSync('gh', [
      'pr',
      'create',
      '--base', 'main',
      '--head', branchName,
      '--title', prTitle,
      '--body', prBody
    ]);

    console.log(`Created PR for issue #${issueNumber}`);
  } catch (err) {
    console.error('Fix agent failed:', err);
    process.exit(1);
  }
}

main();
